@@ -1,5 +1,30 @@
-{ ... }:
+{ config, lib, pkgs, ... }:
 {
-  # Deployment-specific networks, VM instances and storage belong downstream.
   microvm.host.enable = true;
+
+  # Fully declarative guests: mount each backing filesystem before creating
+  # its share directories or starting the share daemon and guest.
+  systemd.services = lib.mkMerge (lib.mapAttrsToList (name: vm:
+    let
+      sources = map (share: share.source)
+        (lib.filter (share: share.source != "/nix/store") vm.config.config.microvm.shares);
+    in lib.optionalAttrs (sources != [ ]) {
+      "microvm@${name}".unitConfig.RequiresMountsFor = sources;
+      "microvm-virtiofsd@${name}" = {
+        unitConfig.RequiresMountsFor = sources;
+        requires = [ "microvm-storage-${name}.service" ];
+        after = [ "microvm-storage-${name}.service" ];
+      };
+      "microvm-storage-${name}" = {
+        description = "Prepare mounted storage for MicroVM ${name}";
+        unitConfig.RequiresMountsFor = sources;
+        serviceConfig = {
+          Type = "oneshot";
+          RemainAfterExit = true;
+          ExecStart = "${pkgs.systemd}/bin/systemd-tmpfiles --create "
+            + lib.escapeShellArgs (map (source: "--prefix=${source}") sources);
+        };
+      };
+    }
+  ) (lib.filterAttrs (_: vm: vm.config != null) config.microvm.vms));
 }
diff --git a/vm-modules/persistent.nix b/vm-modules/persistent.nix
new file mode 100644
index 0000000..6746baf
--- /dev/null
+++ b/vm-modules/persistent.nix
@@ -0,0 +1,34 @@
+{ config, lib, ... }:
+{
+  options.nexus.persistence = lib.mkOption {
+    default = { };
+    description = "Named guest storage requests, with backing directories assigned by the deployment.";
+    type = lib.types.attrsOf (lib.types.submodule {
+      options = {
+        mountPoint = lib.mkOption {
+          type = lib.types.str;
+          description = "Absolute mount point inside the guest.";
+        };
+        source = lib.mkOption {
+          type = lib.types.str;
+          description = "Absolute host directory supplied by the deployment's storage mapping.";
+        };
+      };
+    });
+  };
+
+  config = {
+    assertions = lib.mapAttrsToList (name: storage: {
+      assertion = builtins.match "[a-zA-Z0-9_-]+" name != null
+        && lib.hasPrefix "/" storage.mountPoint
+        && lib.hasPrefix "/" storage.source;
+      message = "Persistent share ${name} requires a simple name and absolute host/guest paths.";
+    }) config.nexus.persistence;
+
+    microvm.shares = lib.mapAttrsToList (name: storage: {
+      tag = name;
+      proto = "virtiofs";
+      inherit (storage) source mountPoint;
+    }) config.nexus.persistence;
+  };
+}
